// Edit supabase/functions/_shared/* and <fn>/source.ts, then re-run the bundler.

// ---------------------------------------------------------------------------
// WorkSense Skill Intelligence Graph engine — the shared, deterministic core.
// Zero LLM calls. Imported by backend functions (Recruitment, Onboarding,
// Recommendation Hub) — never recomputed per page view; results are persisted
// into digital_twins.computed_fits[] and, for skill-match, the durable
// skill_fits table.
//
// Phase 8: every fit is versioned against the engine, the person's evidence
// and the requisition content; cached results are marked stale when any of
// them change. Adjacency and transferable support carry explicit limitations
// (never direct equivalence). The evidence section counts DISTINCT artifacts,
// not skill assertions.
// ---------------------------------------------------------------------------

export type VerificationRigor = "low" | "medium" | "high";

/** Bump when the scoring semantics change — stale cached fits are recomputed. */
export const ENGINE_VERSION = "2";

export interface SkillClaim {
  name: string;
  proficiency: number;
  evidence_source: string;
  verification_rigor: VerificationRigor;
}

export type EdgeType = "PREREQUISITE_OF" | "ADJACENT_TO" | "TRANSFERABLE_TO";

export interface GraphEdge {
  target_skill: string;
  type: EdgeType;
  weight: number; // 0.0 - 1.0
}

export interface GraphSkill {
  skill: string;
  category: string;
  outgoing_edges: GraphEdge[];
}

export interface RequiredSkill {
  skill: string;
  target_proficiency: number;
}

export type Classification = "direct" | "adjacent" | "transferable" | "gap";

export interface FitItem {
  skill: string;
  classification: Classification;
  required_proficiency: number;
  candidate_proficiency: number | null;
  edge: { from_skill: string; type: EdgeType; weight: number } | null;
  contribution: number | null;
  reason: string;
  /** Phase 8: honest limitation of this classification (never equivalence).
   *  Optional so legacy generated fits remain valid. */
  limitation?: string | null;
}

export interface FitRecord {
  target_type: "requisition";
  target_id: string;
  target_title: string;
  scenario: "current" | "future";
  score: number;
  sections: {
    direct: { value: number; items: FitItem[] };
    adjacent: { value: number; items: FitItem[] };
    evidence: { value: number; artifact_count: number; threshold: number };
    seniority: { value: number; candidate_level: number; role_level: number };
  };
  classification: {
    direct: FitItem[];
    adjacent: FitItem[];
    transferable: FitItem[];
    gaps: FitItem[];
  };
  /** Phase 8: what the fit is versioned against (stale detection). Optional so
   *  legacy generated fits remain valid; missing versions are treated as stale. */
  versions?: {
    engine: string;
    evidence: string;
    requisition: string;
  };
  /** Phase 8: named horizon + assumption the fit was computed under. */
  assumptions?: {
    horizon: string;
    note: string;
  };
  computed_at: string;
}

// Validated weights — do not change.
export const MATCH_WEIGHTS = {
  direct: 0.5,
  adjacent: 0.25,
  evidence: 0.15,
  seniority: 0.1,
} as const;

export const DEFAULT_EVIDENCE_THRESHOLD = 5;

const norm = (s: string) => s.trim().toLowerCase();

export function findEdge(
  skillGraph: GraphSkill[],
  from: string,
  to: string,
  type: EdgeType
): GraphEdge | null {
  const node = skillGraph.find((n) => norm(n.skill) === norm(from));
  const edge = node?.outgoing_edges.find(
    (e) => norm(e.target_skill) === norm(to) && e.type === type
  );
  return edge ?? null;
}

const round3 = (n: number) => Math.round(n * 1000) / 1000;

/** Deterministic FNV-1a hex (uniquely named to avoid bundle collisions). */
export function graphFnv1aHex(str: string): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, "0");
}

/** Version hash over the requisition's skill content (phase 8 stale check). */
export function requisitionContentHash(
  requiredSkills: RequiredSkill[],
  futureSkills: RequiredSkill[],
  seniorityLevel: number
): string {
  const payload = [
    ...(requiredSkills ?? []).map((s) => `${s.skill}|${s.target_proficiency}`).sort(),
    ...(futureSkills ?? []).map((s) => `future:${s.skill}|${s.target_proficiency}`).sort(),
    `level:${seniorityLevel}`,
  ].join(";");
  return graphFnv1aHex(payload);
}

/** Version hash over the person's resolved skill claims (evidence version). */
export function claimHash(claims: SkillClaim[]): string {
  const payload = (claims ?? [])
    .map((c) => `${c.name}|${c.proficiency}|${c.evidence_source}|${c.verification_rigor}`)
    .sort()
    .join(";");
  return graphFnv1aHex(payload);
}

/** Phase 8: a cached fit is stale when the engine, the person's evidence or
 *  the requisition content changed since it was computed. */
export function fitIsStale(fit: FitRecord | null, current: { engine: string; evidence: string; requisition: string }): boolean {
  if (!fit) return true;
  const v = fit.versions;
  if (!v) return true; // pre-version fits are always stale
  return v.engine !== current.engine || v.evidence !== current.evidence || v.requisition !== current.requisition;
}

const HORIZON_LABEL: Record<string, string> = {
  current: "Current requirements — as recorded on the requisition today.",
  future: "12–24 month outlook — derived from the requisition's future_skills. Assumption: these skills are the expected demand; edit the requisition to change them.",
};

export function computeFit(params: {
  candidateSkills: SkillClaim[];
  candidateLevel: number;
  requiredSkills: RequiredSkill[];
  roleLevel: number;
  skillGraph: GraphSkill[];
  threshold?: number;
  target: { type: "requisition"; id: string; title: string };
  scenario: "current" | "future";
  computedAt?: string;
  /** Phase 8: distinct artifact count behind the claims (dedup, never
   *  one-per-assertion). Falls back to claim count when not supplied. */
  evidenceArtifactCount?: number;
  /** Phase 8: requisition content hash (stale detection). */
  requisitionVersion?: string;
}): FitRecord {
  const threshold = params.threshold ?? DEFAULT_EVIDENCE_THRESHOLD;
  const graph = params.skillGraph;

  const directItems: FitItem[] = [];
  const adjacentItems: FitItem[] = [];
  const transferableItems: FitItem[] = [];
  const gapItems: FitItem[] = [];
  const directValues: number[] = [];
  const adjacentValues: number[] = [];

  let ownedCount = 0;
  for (const req of params.requiredSkills) {
    const own = params.candidateSkills.find((s) => norm(s.name) === norm(req.skill));
    const ownProficiency = own?.proficiency ?? 0;

    // S_direct: min(1, candidate/required) across ALL required skills — 0 for
    // skills not owned; partial proficiency still contributes its ratio.
    const ratio = own ? Math.min(1, ownProficiency / req.target_proficiency) : 0;
    directValues.push(ratio);

    if (own) {
      ownedCount++;
      if (ownProficiency >= req.target_proficiency) {
        directItems.push({
          skill: req.skill,
          classification: "direct",
          required_proficiency: req.target_proficiency,
          candidate_proficiency: ownProficiency,
          edge: null,
          contribution: ratio,
          reason: `Holds ${req.skill} at ${ownProficiency}/${req.target_proficiency} required.`,
          limitation: null,
        });
      } else {
        directItems.push({
          skill: req.skill,
          classification: "direct",
          required_proficiency: req.target_proficiency,
          candidate_proficiency: ownProficiency,
          edge: null,
          contribution: ratio,
          reason: `Holds ${req.skill} at ${ownProficiency}/${req.target_proficiency} — below the required bar.`,
          limitation: null,
        });
      }
      continue;
    }

    // Adjacent: no direct skill, but a real ADJACENT_TO edge exists (with the
    // candidate's proficiency weighting the edge). Never a direct equivalence.
    let bestAdj: { from: string; edge: GraphEdge; value: number } | null = null;
    for (const claim of params.candidateSkills) {
      const edge = findEdge(graph, claim.name, req.skill, "ADJACENT_TO");
      if (edge) {
        const value = (claim.proficiency / 5) * edge.weight;
        if (!bestAdj || value > bestAdj.value) bestAdj = { from: claim.name, edge, value };
      }
    }
    if (bestAdj) {
      adjacentValues.push(bestAdj.value);
      adjacentItems.push({
        skill: req.skill,
        classification: "adjacent",
        required_proficiency: req.target_proficiency,
        candidate_proficiency: ownProficiency || null,
        edge: { from_skill: bestAdj.from, type: "ADJACENT_TO", weight: bestAdj.edge.weight },
        contribution: bestAdj.value,
        reason: `No direct ${req.skill}; backed by ${bestAdj.from} → ${req.skill} (ADJACENT_TO, ${bestAdj.edge.weight.toFixed(2)}).`,
        limitation: "Adjacent support is NOT direct equivalence: this person has no evidence for the required skill itself. Confirm real capability before relying on it.",
      });
      continue;
    }

    // Transferable: no direct/adjacent edge, but a TRANSFERABLE_TO edge or a
    // strong same-category relationship exists.
    let transfer: { from: string; edge: GraphEdge | null; via: string } | null = null;
    for (const claim of params.candidateSkills) {
      const edge = findEdge(graph, claim.name, req.skill, "TRANSFERABLE_TO");
      if (edge) {
        transfer = { from: claim.name, edge, via: "edge" };
        break;
      }
      if (!transfer) {
        const ownNode = graph.find((n) => norm(n.skill) === norm(claim.name));
        const reqNode = graph.find((n) => norm(n.skill) === norm(req.skill));
        if (ownNode && reqNode && ownNode.category && ownNode.category === reqNode.category) {
          transfer = { from: claim.name, edge: null, via: `same category (${ownNode.category})` };
        }
      }
    }
    if (transfer) {
      transferableItems.push({
        skill: req.skill,
        classification: "transferable",
        required_proficiency: req.target_proficiency,
        candidate_proficiency: ownProficiency || null,
        edge: transfer.edge
          ? { from_skill: transfer.from, type: "TRANSFERABLE_TO", weight: transfer.edge.weight }
          : null,
        contribution: null,
        reason: transfer.edge
          ? `No direct or adjacent path; ${transfer.from} → ${req.skill} is transferable.`
          : `No direct or adjacent path; ${transfer.from} shares the ${transfer.via}.`,
        limitation: "Transferable support is the weakest signal: it does not establish any proficiency in the required skill and contributes no points to the score. Treat it as a development candidate, not capability.",
      });
      continue;
    }

    gapItems.push({
      skill: req.skill,
      classification: "gap",
      required_proficiency: req.target_proficiency,
      candidate_proficiency: ownProficiency || null,
      edge: null,
      contribution: null,
      reason: `No direct, adjacent, or transferable path found for ${req.skill}.`,
      limitation: null,
    });
  }

  const S_direct =
    directValues.length > 0
      ? directValues.reduce((a, b) => a + b, 0) / directValues.length
      : 0;

  const missing = params.requiredSkills.length - ownedCount; // skills not owned at all
  const S_adjacent =
    missing === 0
      ? 1 // nothing missing to be adjacent to
      : adjacentValues.length > 0
        ? adjacentValues.reduce((a, b) => a + b, 0) / missing
        : 0;

  // Phase 8: evidence counts DISTINCT artifacts (deduped by source), never one
  // point per skill assertion. Fallback to the claim count for legacy callers.
  const artifactCount =
    params.evidenceArtifactCount !== undefined
      ? params.evidenceArtifactCount
      : params.candidateSkills.filter((s) => s.verification_rigor === "high" || s.verification_rigor === "medium").length;
  const S_evidence = Math.min(1, artifactCount / threshold);

  const S_seniority = Math.max(0, 1 - 0.2 * Math.abs(params.candidateLevel - params.roleLevel));

  const score =
    MATCH_WEIGHTS.direct * S_direct +
    MATCH_WEIGHTS.adjacent * S_adjacent +
    MATCH_WEIGHTS.evidence * S_evidence +
    MATCH_WEIGHTS.seniority * S_seniority;

  return {
    target_type: params.target.type,
    target_id: params.target.id,
    target_title: params.target.title,
    scenario: params.scenario,
    score: round3(score),
    sections: {
      direct: { value: round3(S_direct), items: directItems },
      adjacent: { value: round3(S_adjacent), items: adjacentItems },
      evidence: { value: round3(S_evidence), artifact_count: artifactCount, threshold },
      seniority: {
        value: round3(S_seniority),
        candidate_level: params.candidateLevel,
        role_level: params.roleLevel,
      },
    },
    classification: {
      direct: directItems,
      adjacent: adjacentItems,
      transferable: transferableItems,
      gaps: gapItems,
    },
    versions: {
      engine: ENGINE_VERSION,
      evidence: claimHash(params.candidateSkills),
      requisition: params.requisitionVersion ?? "unknown",
    },
    assumptions: {
      horizon: params.scenario === "future" ? "12–24 month outlook" : "Current",
      note: HORIZON_LABEL[params.scenario],
    },
    computed_at: params.computedAt ?? new Date().toISOString(),
  };
}

/** Cache key for computed_fits[] entries. */
export function fitKey(record: { target_type: string; target_id: string; scenario: string }) {
  return `${record.target_type}|${record.target_id}|${record.scenario}`;
}


// ---------------------------------------------------------------------------
// Workforce Review Index engine — deterministic, zero LLM.
// An interpretable, decision-support composite (0-100) that flags WHEN a
// manager/HR review conversation is warranted. It is a REVIEW INDEX, never a
// probability of leaving, and never a performance verdict on its own.
//
// Documented design (Phase 9 baseline, Phase 7 hardened):
// - Factor weights sum to EXACTLY 1.0 (max index = 100).
// - Missing observations are gaps that reduce data completeness; they never
//   count as poor performance and never push anyone into the top tier.
// - A zero attendance baseline does NOT produce an extreme ratio: an absence
//   pattern appearing where none was recorded scores a fixed moderate step.
// - Seeking growth / development interest is reported SEPARATELY and never
//   contributes to the index (growth interest != intent to leave).
// - Priority tiers: low < 40, medium 40-59, high 60-74, review >= 75 (the
//   top tier additionally requires >= REVIEW_MIN_COMPLETENESS data).
// - Phase 7: observed factors, coverage, freshness and review confidence are
//   reported SEPARATELY. Data-quality problems surface BEFORE classification
//   (flags + severity + confidence), insufficient history is distinguished
//   from stable behavior (history_state), and every trend carries explicit
//   favorable/unfavorable semantics. No validated predictive model exists:
//   REVIEW_MODEL_STATUS documents what a future attrition model would require.
// ---------------------------------------------------------------------------

export interface ReviewObservation {
  metric: string; // attendance | engagement | delivery | availability
  period: string; // YYYY-MM
  value: number | null;
  missing: boolean;
}

export interface ReviewIndexInput {
  twin_id?: string;
  promotion_lag_months: number; // months in current band without promotion
  promotion_threshold_months?: number; // default 36 (career-review horizon)
  attendance?: { baseline?: number | null; recent?: number | null }; // unapproved absences/month snapshot
  delivery?: { missed?: number | null; total?: number | null }; // missed milestones / window total
  observations?: ReviewObservation[]; // period-scoped, explicit missing flag
  seeks_growth?: boolean; // self-reported development interest — NEVER adds risk
  engagement_window_months?: number; // default 6
  computed_at?: string; // ISO timestamp for freshness computations
}

export interface ReviewFactor {
  score: number; // 0-1
  weight: number; // factor weight (weights sum to 1.0)
  definition: string; // plain-language factor definition
  source_period: string | null; // evidence period used (or null when n/a)
  note: string | null; // caveat / data-state note
  /** Phase 7: coverage of the evidence this factor relies on (0-1). */
  coverage: number;
  /** Phase 7: how fresh the factor's evidence is (latest period used, or null). */
  freshness: string | null;
}

export interface ReviewTrend {
  metric: string;
  direction: "up" | "down" | "flat" | "insufficient";
  delta: number | null; // (last-first)/first on present values
  first: number | null;
  last: number | null;
  periods: string[];
  /** Phase 7: canonical direction that counts as favorable for this metric. */
  favorable_direction: "up" | "down";
  /** Phase 7: whether the observed change is favorable for the metric. */
  favorable: boolean;
}

/** Phase 7: review confidence — how much the index can be trusted given the
 *  data, NOT a probability of leaving and NOT model calibration. */
export type ReviewConfidence = "high" | "medium" | "low";

export interface DataQualityIssue {
  kind: string; // missing_periods | stale_observations | zero_history | snapshot_only
  detail: string;
}

export interface ReviewIndexResult {
  index: number; // 0-100, weights sum to 1.0
  factors: Record<"career" | "attendance" | "delivery" | "engagement", ReviewFactor>;
  trend: ReviewTrend[];
  data_completeness: number; // 0-1 fraction of expected observation slots present
  missing_data: { metric: string; periods: string[] }[];
  seeking_growth: boolean; // reported separately; NOT part of the index
  priority: "low" | "medium" | "high" | "review";
  priority_gate: { tier_capped: boolean; reason: string | null };
  recommended_fact_finding: string[];
  sensitivity: { individual_absence: boolean; individual_engagement: boolean };
  limitations: string[];
  // Phase 7 additions:
  confidence: ReviewConfidence;
  confidence_reason: string;
  history_state: "none" | "partial" | "adequate";
  data_quality: { issues: DataQualityIssue[]; severity: "ok" | "warning" | "critical" };
  freshness: {
    oldest_observation_period: string | null;
    latest_observation_period: string | null;
    months_since_latest: number | null;
    stale: boolean;
    computed_at: string;
  };
  case_rationale: { factor: string; why: string }[];
}

/** Canonical review bands — the single source of truth the UI and backend both
 *  use so "review bands match across UI and backend". */
export const REVIEW_BANDS: Record<"low" | "medium" | "high" | "review", { min: number; max: number }> = {
  low: { min: 0, max: 39 },
  medium: { min: 40, max: 59 },
  high: { min: 60, max: 74 },
  review: { min: 75, max: 100 },
};

export const REVIEW_BAND_LABELS: Record<keyof typeof REVIEW_BANDS, string> = {
  low: "Low (0-39)",
  medium: "Medium (40-59)",
  high: "High (60-74)",
  review: "Review (75-100)",
};

/** Map an index value to its canonical band (backend + UI agree on this). */
export function reviewBandFor(index: number): "low" | "medium" | "high" | "review" {
  if (index >= REVIEW_BANDS.review.min) return "review";
  if (index >= REVIEW_BANDS.high.min) return "high";
  if (index >= REVIEW_BANDS.medium.min) return "medium";
  return "low";
}

/** Phase 7: per-metric semantics so trends are rendered with the CORRECT
 *  favorable/unfavorable meaning (attendance up = bad; delivery/engagement
 *  up = good). */
export const REVIEW_METRIC_FAVORABLE_DIRECTION: Record<string, "up" | "down"> = {
  attendance: "down",
  delivery: "up",
  engagement: "up",
};

export type ReviewBand = "low" | "medium" | "high" | "review";

/** Phase 7: fewer distinct present periods than this = "insufficient history"
 *  (distinct from stable behavior, which requires enough data to actually be flat). */
export const REVIEW_HISTORY_MIN_PERIODS = 3;
/** Phase 7: latest observation older than this many months = stale. */
export const STALE_OBSERVATION_MONTHS = 6;

/** Phase 7 — honest model status. No validated attrition/predictive model
 *  exists; this is the (unchanged) honest REVIEW INDEX terminology the spec
 *  asks to preserve. The future-ML checklist (spec items 21-26) is documented
 *  here so nobody mistakes the heuristic composite for a calibrated predictor. */
export const REVIEW_MODEL_STATUS = {
  has_validated_predictive_model: false,
  label: "Workforce Review Index — a documented heuristic composite (0-100), not a probability of leaving and not a calibrated prediction.",
  future_ml_requirements: [
    "21. Define an explicit outcome (e.g., voluntary attrition within a horizon) and a prediction horizon.",
    "22. Split by time (train on earlier periods, evaluate on later) and prevent post-outcome leakage.",
    "23. Compare against interpretable baselines (e.g., historical base rate) before any complex model.",
    "24. Report calibration, precision/recall, cohort stability and missingness handling.",
    "25. Clearly distinguish synthetic-data demonstrations from externally validated predictive performance.",
    "26. Keep any future prediction as restricted decision support, never automatic action.",
  ],
  note: "None of the above is implemented because no suitable labeled outcome dataset exists in this deployment. Until it does, every case stays a review index with documented heuristics.",
} as const;

// Weights — sum is exactly 1.0 (0.30 + 0.30 + 0.30 + 0.10).
export const REVIEW_WEIGHTS = { career: 0.3, attendance: 0.3, delivery: 0.3, engagement: 0.1 } as const;
export const CAREER_REVIEW_THRESHOLD_MONTHS = 36;
export const ATTENDANCE_CAP_RATIO = 2; // doubling the baseline absence rate = full factor
export const ZERO_BASELINE_STEP = 0.5; // fixed moderate step (NOT 1.0) when a pattern appears from zero
export const REVIEW_MIN_COMPLETENESS = 0.75; // top tier requires at least this much data
export const TREND_HALF_PERIODS = 3; // compare means of first/last N present periods

function clamp01(v: number): number {
  return Math.min(1, Math.max(0, v));
}

function presentValues(obs: ReviewObservation[], metric: string): { period: string; value: number }[] {
  return (obs ?? [])
    .filter((o) => o.metric === metric && !o.missing && typeof o.value === "number")
    .sort((a, b) => a.period.localeCompare(b.period))
    .map((o) => ({ period: o.period, value: o.value as number }));
}

export function computeReviewIndex(input: ReviewIndexInput): ReviewIndexResult {
  const threshold = input.promotion_threshold_months ?? CAREER_REVIEW_THRESHOLD_MONTHS;
  const engWindow = input.engagement_window_months ?? 6;
  const obs = input.observations ?? [];
  const seeksGrowth = input.seeks_growth === true;
  const computedAt = input.computed_at ?? new Date().toISOString();

  // --- F_career: time in band beyond the career-review horizon --------------
  const lag = Math.max(0, Number(input.promotion_lag_months) || 0);
  const career = clamp01(lag / threshold);
  const careerFactor: ReviewFactor = {
    score: career,
    weight: REVIEW_WEIGHTS.career,
    definition: `Months in current band without a promotion, scaled against the ${threshold}-month career-review horizon.`,
    source_period: "twin profile (as of computed_at)",
    coverage: 1,
    freshness: "profile snapshot",
    note: career >= 0.5 ? "Extended time in band warrants a career-path conversation — not, by itself, a risk conclusion." : null,
  };

  // --- F_attendance: deviation of recent absence rate from OWN baseline ------
  const base = input.attendance?.baseline;
  const recent = input.attendance?.recent;
  let attendanceScore = 0;
  let attendanceNote: string | null = null;
  const attendanceCoverage = base === null || base === undefined || recent === null || recent === undefined ? 0 : 1;
  if (attendanceCoverage === 0) {
    attendanceNote = "No absence snapshot recorded — treated as unknown, not penalized.";
  } else if (Number(base) > 0) {
    const b = Math.max(0, Number(base));
    const r = Math.max(0, Number(recent));
    if (r > b) {
      attendanceScore = clamp01((r / b - 1) / (ATTENDANCE_CAP_RATIO - 1));
      if (attendanceScore >= 0.5) attendanceNote = "Recent absence rate is materially above this person's own baseline — verify with the manager.";
    }
  } else {
    // Zero baseline: fixed moderate step, never an extreme ratio from 0.
    attendanceScore = Math.max(0, Number(recent)) > 0 ? ZERO_BASELINE_STEP : 0;
    if (attendanceScore > 0) {
      attendanceNote = `No unapproved absence was recorded before; a pattern appeared (scored a fixed ${ZERO_BASELINE_STEP} step to avoid an extreme ratio from a zero baseline).`;
    }
  }
  const attendanceFactor: ReviewFactor = {
    score: attendanceScore,
    weight: REVIEW_WEIGHTS.attendance,
    definition: "Deviation of the recent unapproved-absence rate from the person's own baseline (pattern change, never cross-person counts).",
    source_period: "most recent absence snapshot (HRIS)",
    coverage: attendanceCoverage,
    freshness: "HRIS snapshot",
    note: attendanceNote,
  };

  // --- F_delivery: missed milestones / window total --------------------------
  const total = Math.max(0, Number(input.delivery?.total) || 0);
  const missed = Math.max(0, Math.min(total, Number(input.delivery?.missed) || 0));
  const deliveryScore = total > 0 ? missed / total : 0;
  const deliveryFactor: ReviewFactor = {
    score: deliveryScore,
    weight: REVIEW_WEIGHTS.delivery,
    definition: "Missed milestones as a share of the review window's total — a workload/availability indicator, not a quality verdict.",
    source_period: "recent delivery window (missed/total)",
    coverage: total > 0 ? 1 : 0,
    freshness: "delivery window snapshot",
    note: total <= 0 ? "No delivery observations in window — treated as unknown, not penalized." : deliveryScore >= 0.5 ? "High miss share — investigate workload/resourcing before drawing conclusions." : null,
  };

  // --- F_engagement: trend over the observation window (explicit gaps) -------
  const eng = presentValues(obs, "engagement").slice(-engWindow);
  let engagementScore = 0;
  let engNote: string | null = null;
  if (eng.length < 2) {
    engNote = eng.length === 0 ? "No engagement observations — treated as unknown, not penalized." : "Too few engagement observations to score.";
  } else {
    const half = Math.max(1, Math.floor(eng.length / 2));
    const first = eng.slice(0, half).reduce((s, p) => s + p.value, 0) / half;
    const second = eng.slice(eng.length - half).reduce((s, p) => s + p.value, 0) / half;
    if (first > 0) {
      engagementScore = clamp01((first - second) / first); // decline in engagement raises the factor
      if (engagementScore > 0) engNote = "Engagement observations trend downward across the window.";
    }
  }
  const engagementFactor: ReviewFactor = {
    score: engagementScore,
    weight: REVIEW_WEIGHTS.engagement,
    definition: `Decline in engagement observations over the last ${engWindow} months (first-vs-second-half means). Missing periods are gaps, not poor performance.`,
    source_period: eng.length >= 2 ? `${eng[0].period} → ${eng[eng.length - 1].period}` : null,
    coverage: eng.length >= 2 ? 1 : eng.length === 1 ? 0.5 : 0,
    freshness: eng.length >= 2 ? eng[eng.length - 1].period : null,
    note: engNote,
  };

  // --- Composite index --------------------------------------------------------
  const index = Math.round(
    100 *
      (REVIEW_WEIGHTS.career * career +
        REVIEW_WEIGHTS.attendance * attendanceScore +
        REVIEW_WEIGHTS.delivery * deliveryScore +
        REVIEW_WEIGHTS.engagement * engagementScore)
  );

  // --- Data completeness + missing data --------------------------------------
  const metricsSeen = new Set((obs ?? []).map((o) => o.metric));
  const periodSet = new Set((obs ?? []).map((o) => o.period));
  const expected = metricsSeen.size * periodSet.size;
  const present = (obs ?? []).filter((o) => !o.missing && typeof o.value === "number").length;
  const data_completeness = expected > 0 ? present / expected : 0;

  const missingByMetric = new Map<string, string[]>();
  for (const o of obs ?? []) {
    if (o.missing || o.value === null || o.value === undefined) {
      missingByMetric.set(o.metric, [...(missingByMetric.get(o.metric) ?? []), o.period]);
    }
  }
  const missing_data = [...missingByMetric.entries()]
    .map(([metric, periods]) => ({ metric, periods: periods.sort() }))
    .sort((a, b) => a.metric.localeCompare(b.metric));

  // --- Freshness (Phase 7) ----------------------------------------------------
  const allPresent = (obs ?? [])
    .filter((o) => !o.missing && typeof o.value === "number")
    .map((o) => o.period)
    .sort();
  const oldest = allPresent[0] ?? null;
  const latest = allPresent[allPresent.length - 1] ?? null;
  let monthsSinceLatest: number | null = null;
  if (latest) {
    const [ly, lm] = latest.split("-").map(Number);
    const now = new Date(computedAt);
    monthsSinceLatest = (now.getUTCFullYear() - ly) * 12 + (now.getUTCMonth() + 1 - lm);
  }
  const stale = monthsSinceLatest !== null && monthsSinceLatest > STALE_OBSERVATION_MONTHS;

  // --- History state (Phase 7): insufficient history vs stable behavior ------
  const distinctPresentPeriods = new Set(allPresent).size;
  const history_state: ReviewIndexResult["history_state"] =
    distinctPresentPeriods === 0 ? "none" : distinctPresentPeriods < REVIEW_HISTORY_MIN_PERIODS ? "partial" : "adequate";

  // --- Data quality surfaced BEFORE classification (Phase 7) ------------------
  const issues: DataQualityIssue[] = [];
  if (distinctPresentPeriods === 0) {
    issues.push({ kind: "zero_history", detail: "No longitudinal observations exist — the index reflects profile snapshots only (career lag, absence and delivery snapshots)." });
  } else if (distinctPresentPeriods < REVIEW_HISTORY_MIN_PERIODS) {
    issues.push({ kind: "snapshot_only", detail: `Only ${distinctPresentPeriods} observation period(s) present — trends cannot be established yet.` });
  }
  if (missing_data.length > 0) {
    const missingCount = missing_data.reduce((n, m) => n + m.periods.length, 0);
    issues.push({ kind: "missing_periods", detail: `${missingCount} observation slot(s) missing across ${missing_data.length} metric(s).` });
  }
  if (stale) {
    issues.push({ kind: "stale_observations", detail: `Latest observation is ${monthsSinceLatest} months old (stale threshold: ${STALE_OBSERVATION_MONTHS}).` });
  }
  const severity: ReviewIndexResult["data_quality"]["severity"] =
    distinctPresentPeriods === 0 || data_completeness < 0.4 ? "critical" : data_completeness < REVIEW_MIN_COMPLETENESS || stale ? "warning" : "ok";

  // --- Review confidence (Phase 7): data-driven, explicitly not a probability --
  let confidence: ReviewConfidence;
  let confidence_reason: string;
  if (distinctPresentPeriods === 0 || data_completeness < 0.5 || stale) {
    confidence = "low";
    confidence_reason = `Low — longitudinal observation history is ${distinctPresentPeriods === 0 ? "absent" : "incomplete"} (${Math.round(data_completeness * 100)}% complete${stale ? ", stale" : ""}). Use the index as a starting point, not a signal.`;
  } else if (data_completeness < REVIEW_MIN_COMPLETENESS || distinctPresentPeriods < 6) {
    confidence = "medium";
    confidence_reason = `Medium — coverage is ${Math.round(data_completeness * 100)}% across ${distinctPresentPeriods} period(s); confirm with a conversation before any conclusion.`;
  } else {
    confidence = "high";
    confidence_reason = `High — coverage is ${Math.round(data_completeness * 100)}% across ${distinctPresentPeriods} period(s) and observations are fresh.`;
  }

  // --- Trend per metric (favorable/unfavorable semantics) ---------------------
  const trend: ReviewTrend[] = ["attendance", "engagement", "delivery"].map((metric) => {
    const vals = presentValues(obs, metric);
    const favorable_direction = REVIEW_METRIC_FAVORABLE_DIRECTION[metric] ?? "up";
    if (vals.length < 2 * TREND_HALF_PERIODS) {
      return { metric, direction: "insufficient", delta: null, first: null, last: null, periods: vals.map((v) => v.period), favorable_direction, favorable: false };
    }
    const firstMean = vals.slice(0, TREND_HALF_PERIODS).reduce((s, p) => s + p.value, 0) / TREND_HALF_PERIODS;
    const lastMean = vals.slice(-TREND_HALF_PERIODS).reduce((s, p) => s + p.value, 0) / TREND_HALF_PERIODS;
    const delta = firstMean > 0 ? (lastMean - firstMean) / firstMean : null;
    const eps = 0.03;
    const direction = delta === null || Math.abs(delta) < eps ? "flat" : delta > 0 ? "up" : "down";
    const favorable = direction === favorable_direction;
    return { metric, direction, delta, first: +firstMean.toFixed(3), last: +lastMean.toFixed(3), periods: vals.map((v) => v.period), favorable_direction, favorable };
  });

  // --- Priority tier (review index, not probability) -------------------------
  let priority: ReviewIndexResult["priority"] = "low";
  if (index >= 75) priority = "review";
  else if (index >= 60) priority = "high";
  else if (index >= 40) priority = "medium";

  let tierCapped = false;
  let gateReason: string | null = null;
  if (priority === "review" && history_state === "none") {
    priority = "high";
    tierCapped = true;
    gateReason = "The index qualifies for the top tier on profile snapshots alone, but there is zero longitudinal observation history — the case is honestly capped until history exists. It is not an alarming classification on no data.";
  } else if (priority === "review" && data_completeness < REVIEW_MIN_COMPLETENESS) {
    priority = "high";
    tierCapped = true;
    gateReason = `Index qualifies for the top tier, but observation data completeness is ${Math.round(data_completeness * 100)}% (min ${Math.round(REVIEW_MIN_COMPLETENESS * 100)}% required) — missing data never escalates a case; complete the gaps before treating this as a top-priority review.`;
  }

  // --- Recommended fact-finding (deterministic, action-oriented) -------------
  const recommended_fact_finding: string[] = [];
  const case_rationale: { factor: string; why: string }[] = [];
  if (attendanceScore >= 0.5) {
    recommended_fact_finding.push("Verify the unapproved-absence pattern with the employee's manager before any conclusion.");
    case_rationale.push({ factor: "attendance", why: attendanceNote ?? "The recent absence rate is materially above the person's own baseline." });
  }
  const engTrendDir = trend.find((t) => t.metric === "engagement")?.direction ?? "insufficient";
  if (engagementScore >= 0.5 || engTrendDir === "down" || engTrendDir === "insufficient") {
    recommended_fact_finding.push("Collect an engagement pulse and discuss drivers in a 1:1 — do not infer reasons from the numbers.");
    if (engTrendDir === "down") case_rationale.push({ factor: "engagement", why: "Engagement observations trend downward across the window." });
    else if (engTrendDir === "insufficient") case_rationale.push({ factor: "engagement", why: "Engagement history is insufficient to judge direction — a conversation is the only honest next step." });
  }
  if (career >= 0.5) {
    recommended_fact_finding.push("Open a career-path conversation; review band-change timing and growth options.");
    case_rationale.push({ factor: "career", why: `${Math.round(lag)} months in band without a promotion — beyond the ${threshold}-month career-review horizon.` });
  }
  if (deliveryScore >= 0.5) {
    recommended_fact_finding.push("Review workload and resourcing; distinguish missed deadlines caused by capacity from quality issues.");
    case_rationale.push({ factor: "delivery", why: `${Math.round(missed)} of ${Math.round(total)} milestones missed in the delivery window.` });
  }
  if (data_completeness < REVIEW_MIN_COMPLETENESS) {
    recommended_fact_finding.push(`Observation history is ${Math.round(data_completeness * 100)}% complete — collect the missing periods before finalizing the review.`);
  }
  if (seeksGrowth) {
    recommended_fact_finding.push("Reported development interest is a growth conversation, not a risk signal — plan scope/mentoring, do not flag for retention.");
  }

  return {
    index,
    factors: { career: careerFactor, attendance: attendanceFactor, delivery: deliveryFactor, engagement: engagementFactor },
    trend,
    data_completeness: +data_completeness.toFixed(3),
    missing_data,
    seeking_growth: seeksGrowth,
    priority,
    priority_gate: { tier_capped: tierCapped, reason: gateReason },
    recommended_fact_finding,
    sensitivity: { individual_absence: attendanceScore > 0, individual_engagement: eng.length >= 2 },
    limitations: [
      "Workforce Review Index is an interpretable decision-support composite (0-100), NOT a probability of leaving.",
      "Factor weights and definitions are fixed, documented heuristics; validate local assumptions before operational use.",
      "Missing observations are treated as data gaps (lower completeness), never as poor performance.",
      "Seeking-growth / development interest is reported separately and never contributes to the index.",
      "The attendance factor uses the most recent absence snapshot; confirm with the manager before conclusions.",
      "Review confidence reflects data coverage and freshness — it is not a calibrated model reliability measure.",
    ],
    confidence,
    confidence_reason,
    history_state,
    data_quality: { issues, severity },
    freshness: {
      oldest_observation_period: oldest,
      latest_observation_period: latest,
      months_since_latest: monthsSinceLatest,
      stale,
      computed_at: computedAt,
    },
    case_rationale,
  };
}

// Stable version hash over the index-relevant source rows. Used to detect when
// cached review artifacts must be invalidated because the underlying data changed.
export function reviewSourceHash(input: ReviewIndexInput): string {
  const payload = {
    lag: input.promotion_lag_months,
    threshold: input.promotion_threshold_months ?? CAREER_REVIEW_THRESHOLD_MONTHS,
    attendance: input.attendance ?? {},
    delivery: input.delivery ?? {},
    seeks_growth: input.seeks_growth === true,
    observations: (input.observations ?? [])
      .map((o) => `${o.metric}|${o.period}|${String(o.value)}|${o.missing ? 1 : 0}`)
      .sort(),
  };
  return fnv1aHex(JSON.stringify(payload));
}

// FNV-1a 32-bit, hex — deterministic across platforms.
// Named fnv1aHex (not fnv1a) so the flat function bundle never collides with
// other shared modules that keep a private fnv1a.
export function fnv1aHex(str: string): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, "0");
}


import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.0";



const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });

const URGENCY_RANK: Record<string, number> = { critical: 0, high: 1, medium: 2, low: 3 };
// Review-priority threshold: index >= 60 is a high-priority review case.
// The index is decision support, never a probability of leaving.
export const REVIEW_THRESHOLD = 60;

const REQ_STATUSES = ["open", "on_hold", "filled", "closed"] as const;

// Phase 12: explicit metric definitions travel with the payload so every number
// on the dashboard can answer "what exactly does this count, and who is in it?".
const DEFINITIONS = {
  headcount:
    "Active workers included in scope: digital twins with role employee or manager and status 'active'. Candidates, offboarding, and service owners are excluded. Candidate twins have status 'candidate', so they never count.",
  open_requisitions:
    "Job requisitions with status 'open'. Requisitions on hold, filled, or closed are counted separately and excluded.",
  active_candidates:
    "Applicants on open requisitions whose stage is still in progress (not selected or rejected).",
  journeys:
    "Workers in scope with an active adaptive onboarding plan (latest non-superseded version). A journey is blocked when any plan task is in state blocked or failed — the same rule the onboarding center uses.",
  heatmap:
    "Per open requisition and future skill, every scoped worker falls into exactly one bucket: ready (verified direct match at/above target), below_target (direct match below the target bar), adjacent_support (adjacent/transferable path, no direct match), insufficient_evidence (no verified path — only claimed/extracted assertions), or missing (no evidence of any kind).",
};

// BFS the manager tree once from the caller — one table load, no per-twin
// lookups. Returns the caller's whole reporting subtree including themselves.
function buildTeamMemberIds(allTwins: { id: string; manager_id: string | null }[], rootId: string): Set<string> {
  const children = new Map<string, string[]>();
  for (const t of allTwins) {
    if (t.manager_id) children.set(t.manager_id, [...(children.get(t.manager_id) ?? []), t.id]);
  }
  const seen = new Set<string>();
  const stack = [rootId];
  while (stack.length > 0) {
    const cur = stack.pop()!;
    if (seen.has(cur)) continue;
    seen.add(cur);
    for (const c of children.get(cur) ?? []) stack.push(c);
  }
  return seen;
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
  );

  const authHeader = req.headers.get("Authorization") ?? "";
  const { data: userData } = await supabase.auth.getUser(authHeader.replace("Bearer ", ""));
  const uid = userData?.user?.id;
  if (!uid) return json({ error: "UNAUTHENTICATED" }, 401);

  const { data: caller } = await supabase
    .from("digital_twins")
    .select("id, role, org_id, department")
    .eq("auth_user_id", uid)
    .maybeSingle();
  if (!caller) return json({ error: "UNAUTHENTICATED" }, 401);

  // Scope is decided SERVER-side from the caller's role — never from the client.
  let scope: "org" | "team";
  if (["hr_executive", "hr_partner"].includes(caller.role)) scope = "org";
  else if (caller.role === "manager") scope = "team";
  else return json({ error: "FORBIDDEN", message: "Dashboard requires HR or Manager access." }, 403);

  // Optional filters from the client body, validated server-side. Filters can
  // only narrow the server-decided scope — never widen it.
  let body: Record<string, unknown> = {};
  try {
    body = await req.json();
  } catch {
    /* empty body is fine */
  }
  const department = typeof body.department === "string" && body.department.trim() ? body.department.trim() : null;
  const requisitionId = typeof body.requisition_id === "string" && body.requisition_id.trim() ? body.requisition_id.trim() : null;
  const period = typeof body.period === "string" && /^\d{4}-\d{2}$/.test(body.period) ? body.period : null;
  const reviewBand = typeof body.review_band === "string" && body.review_band in REVIEW_BANDS ? (body.review_band as ReviewBand) : null;
  const minCompleteness = typeof body.min_completeness === "number" && body.min_completeness >= 0 && body.min_completeness <= 1 ? body.min_completeness : null;

  // Load all org twins once, then resolve the scoped set.
  const { data: allTwins } = await supabase
    .from("digital_twins")
    .select("id, name, role, status, org_id, signals, seniority_level, verified_skills, manager_id, attendance, delivery, promotion_lag_months, department")
    .eq("org_id", caller.org_id);

  let scoped = (allTwins ?? []).filter((t) => t.status === "active" && ["employee", "manager"].includes(t.role));
  if (scope === "team") {
    const memberIds = buildTeamMemberIds(allTwins ?? [], caller.id);
    scoped = scoped.filter((t) => memberIds.has(t.id));
  }
  if (department) {
    const dept = department.toLowerCase();
    scoped = scoped.filter((t) => (t.department ?? "").toLowerCase() === dept);
  }
  const scopedIds = new Set(scoped.map((t) => t.id));

  // Longitudinal observations for the scoped set (period-scoped, explicit gaps).
  const { data: obsRows } = await supabase
    .from("workforce_observations")
    .select("twin_id, metric, period_start, value, missing")
    .eq("org_id", caller.org_id)
    .in("twin_id", [...scopedIds]);
  let obs = (obsRows ?? []).map((o) => ({
    twin_id: o.twin_id,
    metric: o.metric,
    period: String(o.period_start).slice(0, 7),
    value: typeof o.value === "number" ? o.value : null,
    missing: o.missing === true,
  }));
  const periodBounds = obs.length > 0
    ? { start: [...obs].sort((a, b) => a.period.localeCompare(b.period))[0].period, end: [...obs].sort((a, b) => b.period.localeCompare(a.period))[0].period }
    : null;
  if (period) obs = obs.filter((o) => o.period === period);
  const obsByTwin = new Map<string, { metric: string; period: string; value: number | null; missing: boolean }[]>();
  for (const o of obs) obsByTwin.set(o.twin_id, [...(obsByTwin.get(o.twin_id) ?? []), o]);

  const reviewIndex = (t: { signals?: { type?: string }[]; attendance?: unknown; delivery?: unknown; promotion_lag_months?: number; id: string }) => {
    const signals = (t.signals ?? []) as { type?: string; value?: unknown }[];
    const seeks = signals.some((s) => s.type === "seeks_growth" && s.value === true);
    const r = computeReviewIndex({
      twin_id: t.id,
      promotion_lag_months: t.promotion_lag_months ?? 0,
      attendance: (t.attendance ?? {}) as { baseline?: number; recent?: number },
      delivery: (t.delivery ?? {}) as { missed?: number; total?: number },
      observations: obsByTwin.get(t.id) ?? [],
      seeks_growth: seeks,
    });
    return r;
  };
  const scopedWithIndex = scoped.map((t) => ({ twin: t, index: reviewIndex(t) }));
  let reviewCases = scopedWithIndex
    .map((x) => ({
      twin_id: x.twin.id,
      name: x.twin.name,
      index: x.index.index,
      priority: x.index.priority,
      completeness: x.index.data_completeness,
      confidence: x.index.confidence,
      history_state: x.index.history_state,
      seeking_growth: x.index.seeking_growth,
    }))
    .sort((a, b) => b.index - a.index);
  if (reviewBand) {
    const band = REVIEW_BANDS[reviewBand];
    reviewCases = reviewCases.filter((c) => c.index >= band.min && c.index <= band.max);
  }
  if (minCompleteness !== null) {
    reviewCases = reviewCases.filter((c) => c.completeness >= minCompleteness);
  }

  // Cards — every number from real records; 0 / "No data" when absent.
  const headcount = scoped.length;
  const reviewPriorityCases = reviewCases.filter((c) => c.index >= REVIEW_THRESHOLD || c.priority === "review" || c.priority === "high").length;

  const [reqsRes, recsRes, plansRes, tasksRes] = await Promise.all([
    supabase.from("job_requisitions").select("id, title, department, status, applicants, future_skills, required_skills, seniority_level").eq("org_id", caller.org_id),
    supabase.from("recommendations").select("id, twin_id, category, urgency, status, proposed_action, executive_summary").eq("org_id", caller.org_id).eq("status", "needs_review"),
    supabase.from("onboarding_plans").select("id, twin_id, version, status").eq("org_id", caller.org_id).not("status", "eq", "superseded"),
    supabase.from("onboarding_tasks").select("plan_id, state").eq("org_id", caller.org_id),
  ]);

  const reqs = (reqsRes.data ?? []) as {
    id: string;
    title: string;
    department: string;
    status: string;
    applicants: { stage: string }[];
    future_skills: { skill: string; target_proficiency: number }[];
    required_skills: { skill: string; target_proficiency: number }[];
    seniority_level: number;
  }[];
  const scopedReqs = requisitionId ? reqs.filter((r) => r.id === requisitionId) : reqs;
  const openReqs = scopedReqs.filter((r) => r.status === "open");
  const reqStatusCounts = Object.fromEntries(REQ_STATUSES.map((s) => [s, scopedReqs.filter((r) => r.status === s).length])) as Record<string, number>;
  const applicants = scopedReqs.flatMap((r) => r.applicants ?? []);
  const activeCandidates = applicants.filter((a) => !["selected", "rejected"].includes(a.stage)).length;
  const STAGE_ORDER = ["screening", "technical_interview", "final_round", "selected", "rejected"] as const;
  const activeByStage = Object.fromEntries(STAGE_ORDER.map((s) => [s, 0])) as Record<string, number>;
  for (const a of applicants) {
    const st = String((a as { stage?: string }).stage ?? "");
    if (st in activeByStage) activeByStage[st] += 1;
  }

  // Onboarding journeys are derived from the CANONICAL adaptive plans: a worker
  // in scope has one active plan (latest non-superseded version). A journey is
  // blocked when any task is in state blocked or failed — the same rule as the
  // engine's readiness.blocked_count, so the dashboard agrees with the
  // onboarding center.
  const activePlansByTwin = new Map<string, { id: string; twin_id: string; version: number; status: string }>();
  for (const p of (plansRes.data ?? []) as { id: string; twin_id: string; version: number; status: string }[]) {
    if (!scopedIds.has(p.twin_id)) continue;
    const cur = activePlansByTwin.get(p.twin_id);
    if (!cur || p.version > cur.version) activePlansByTwin.set(p.twin_id, p);
  }
  const activePlans = [...activePlansByTwin.values()];
  const stateByPlan = new Map<string, string[]>();
  for (const t of (tasksRes.data ?? []) as { plan_id: string; state: string }[]) {
    stateByPlan.set(t.plan_id, [...(stateByPlan.get(t.plan_id) ?? []), t.state]);
  }
  const journeysInProgress = activePlans.length;
  const journeysBlocked = activePlans.filter((p) => (stateByPlan.get(p.id) ?? []).some((s) => s === "blocked" || s === "failed")).length;
  const journeysOnTrack = journeysInProgress - journeysBlocked;

  const pendingRecs = (recsRes.data ?? []).filter((r) => scope === "org" || (r.twin_id && scopedIds.has(r.twin_id)));

  // Heatmap: for every OPEN requisition's future skills, bucket each scoped
  // worker into exactly one of missing / below_target / adjacent_support /
  // insufficient_evidence / ready. "Insufficient evidence" means claims exist
  // (claimed or extracted assertions) but no verified skill path does.
  const { data: graphRes } = await supabase
    .from("skill_graph")
    .select("id, skill, category, outgoing_edges")
    .eq("org_id", caller.org_id);
  const graph = (graphRes ?? []) as (GraphSkill & { id: string })[];
  const skillNameById = new Map<string, string>((graph ?? []).map((g) => [g.id, g.skill]));
  const { data: assertionRows } = scopedIds.size > 0
    ? await supabase
        .from("skill_assertions")
        .select("twin_id, skill_id, review_state")
        .eq("org_id", caller.org_id)
        .in("twin_id", [...scopedIds])
        .in("review_state", ["claimed", "extracted"])
    : { data: [] };
  const claimsByTwin = new Map<string, Set<string>>();
  for (const a of assertionRows ?? []) {
    const skillName = skillNameById.get(a.skill_id);
    if (!skillName) continue;
    const set = claimsByTwin.get(a.twin_id) ?? new Set<string>();
    set.add(skillName);
    claimsByTwin.set(a.twin_id, set);
  }

  const heatmap: {
    skill: string;
    target_proficiency: number;
    req_id: string;
    req_title: string;
    buckets: { missing: number; below_target: number; adjacent_support: number; insufficient_evidence: number; ready: number };
    total: number;
  }[] = [];
  for (const req of openReqs) {
    for (const fs of req.future_skills ?? []) {
      const buckets = { missing: 0, below_target: 0, adjacent_support: 0, insufficient_evidence: 0, ready: 0 };
      for (const twin of scoped) {
        const fit = computeFit({
          candidateSkills: (twin.verified_skills ?? []) as { name: string; proficiency: number; evidence_source: string; verification_rigor: "low" | "medium" | "high" }[],
          candidateLevel: twin.seniority_level ?? 3,
          requiredSkills: [{ skill: fs.skill, target_proficiency: fs.target_proficiency }],
          roleLevel: req.seniority_level,
          skillGraph: graph,
          target: { type: "requisition", id: req.id, title: req.title },
          scenario: "future",
        });
        const cls = fit.classification;
        const direct = cls.direct.find((i) => i.skill.toLowerCase() === fs.skill.toLowerCase());
        if (direct) {
          const p = direct.candidate_proficiency ?? 0;
          if (p >= fs.target_proficiency) buckets.ready += 1;
          else buckets.below_target += 1;
        } else if (
          cls.adjacent.some((i) => i.skill.toLowerCase() === fs.skill.toLowerCase()) ||
          cls.transferable.some((i) => i.skill.toLowerCase() === fs.skill.toLowerCase())
        ) {
          buckets.adjacent_support += 1;
        } else if (claimsByTwin.get(twin.id)?.has(fs.skill.toLowerCase()) || claimsByTwin.get(twin.id)?.has(fs.skill)) {
          buckets.insufficient_evidence += 1;
        } else {
          buckets.missing += 1;
        }
      }
      heatmap.push({
        skill: fs.skill,
        target_proficiency: fs.target_proficiency,
        req_id: req.id,
        req_title: req.title,
        buckets,
        total: scoped.length,
      });
    }
  }

  const recommendations = pendingRecs
    .map((r) => ({
      id: r.id,
      category: r.category,
      urgency: r.urgency,
      title: (r.proposed_action as { title?: string })?.title ?? r.category,
      executive_summary: r.executive_summary ?? "",
    }))
    .sort((a, b) => (URGENCY_RANK[a.urgency] ?? 9) - (URGENCY_RANK[b.urgency] ?? 9));

  const availableDepartments = [...new Set((allTwins ?? [])
    .filter((t) => t.status === "active" && ["employee", "manager"].includes(t.role))
    .map((t) => t.department)
    .filter(Boolean))].sort() as string[];
  const availableRequisitions = reqs.map((r) => ({ id: r.id, title: r.title, status: r.status }));

  return json({
    ok: true,
    scope,
    threshold: REVIEW_THRESHOLD,
    computed_at: new Date().toISOString(),
    period: {
      label: period ?? (periodBounds ? `all observations (${periodBounds.start} – ${periodBounds.end})` : "no observations in scope"),
      start: period ?? periodBounds?.start ?? null,
      end: period ?? periodBounds?.end ?? null,
      filtered: !!period,
    },
    // Full observation range regardless of the applied period filter, so the
    // client can keep offering every selectable month.
    observation_range: periodBounds,
    definitions: DEFINITIONS,
    filters: {
      applied: { department, requisition_id: requisitionId, period, review_band: reviewBand, min_completeness: minCompleteness },
      available: { departments: availableDepartments, requisitions: availableRequisitions },
    },
    review_cases: reviewCases,
    // Phase 14: decision-oriented distributions — hiring funnel by stage and
    // review-band counts, each with denominators (sample sizes) so no number
    // floats without context.
    hiring_funnel: STAGE_ORDER.map((stage) => ({
      stage,
      count: activeByStage[stage] ?? 0,
    })),
    review_band_counts: {
      low: reviewCases.filter((c) => c.priority === "low").length,
      medium: reviewCases.filter((c) => c.priority === "medium").length,
      high: reviewCases.filter((c) => c.priority === "high").length,
      review: reviewCases.filter((c) => c.priority === "review").length,
      total: reviewCases.length,
    },
    cards: {
      headcount,
      open_requisitions: openReqs.length,
      requisition_statuses: reqStatusCounts,
      active_candidates: activeCandidates,
      journeys_in_progress: journeysInProgress,
      journeys_on_track: journeysOnTrack,
      journeys_blocked: journeysBlocked,
      review_priority_cases: reviewPriorityCases,
      pending_recommendations: pendingRecs.length,
    },
    heatmap,
    recommendations,
  });
});
